INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 1, 'What must be done before bunkering?', 'A) Plug scuppers', 'B) Start engine', 'C) Paint deck', 'D) Open hatches', 'A', NULL, NULL, 'Prior to commencing bunkering operations, the Chief Engineer must ensure all scuppers are plugged and the SOPEP spill equipment is deployed. The maximum filling limit for any fuel oil tank is 85% to allow for expansion. Constant communication must be maintained between the ship and the bunker barge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 2, 'What is the maximum filling limit?', 'A) 50%', 'B) 85%', 'C) 95%', 'D) 100%', 'B', NULL, NULL, 'Prior to commencing bunkering operations, the Chief Engineer must ensure all scuppers are plugged and the SOPEP spill equipment is deployed. The maximum filling limit for any fuel oil tank is 85% to allow for expansion. Constant communication must be maintained between the ship and the bunker barge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 3, 'Why is the limit set at 85%?', 'A) To save money', 'B) To allow for oil expansion', 'C) To speed up loading', 'D) To reduce weight', 'B', NULL, NULL, 'Prior to commencing bunkering operations, the Chief Engineer must ensure all scuppers are plugged and the SOPEP spill equipment is deployed. The maximum filling limit for any fuel oil tank is 85% to allow for expansion. Constant communication must be maintained between the ship and the bunker barge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 4, 'What is required in restricted visibility?', 'A) Stop the ship', 'B) Post an extra lookout', 'C) Turn off radar', 'D) Go to sleep', 'B', NULL, NULL, 'The Officer of the Watch (OOW) must maintain a proper lookout at all times. In restricted visibility, the OOW must post an extra lookout, start the fog signal, and ensure the engines are ready for immediate maneuver. Relying solely on radar is strictly prohibited.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 5, 'What must be done with the engines?', 'A) Shut them down', 'B) Run at maximum speed', 'C) Keep ready for immediate maneuver', 'D) Overhaul them', 'C', NULL, NULL, 'The Officer of the Watch (OOW) must maintain a proper lookout at all times. In restricted visibility, the OOW must post an extra lookout, start the fog signal, and ensure the engines are ready for immediate maneuver. Relying solely on radar is strictly prohibited.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 6, 'Can the OOW rely only on radar?', 'A) Yes, always', 'B) Yes, in fog', 'C) No, it is strictly prohibited', 'D) Only at night', 'C', NULL, NULL, 'The Officer of the Watch (OOW) must maintain a proper lookout at all times. In restricted visibility, the OOW must post an extra lookout, start the fog signal, and ensure the engines are ready for immediate maneuver. Relying solely on radar is strictly prohibited.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 7, 'How does the purifier separate impurities?', 'A) Chemical reaction', 'B) Centrifugal force', 'C) Heating', 'D) Evaporation', 'B', NULL, NULL, 'The lube oil purifier operates continuously while the main engine is running. It uses centrifugal force to separate water and solid impurities from the lubricating oil. Regular de-sludging is necessary to maintain its efficiency. If excessive vibration occurs, the unit must be stopped immediately.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 8, 'What is required to maintain efficiency?', 'A) Painting', 'B) De-sludging', 'C) Adding water', 'D) Cooling', 'B', NULL, NULL, 'The lube oil purifier operates continuously while the main engine is running. It uses centrifugal force to separate water and solid impurities from the lubricating oil. Regular de-sludging is necessary to maintain its efficiency. If excessive vibration occurs, the unit must be stopped immediately.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 9, 'What should be done if excessive vibration occurs?', 'A) Add more oil', 'B) Ignore it', 'C) Stop the unit immediately', 'D) Increase speed', 'C', NULL, NULL, 'The lube oil purifier operates continuously while the main engine is running. It uses centrifugal force to separate water and solid impurities from the lubricating oil. Regular de-sludging is necessary to maintain its efficiency. If excessive vibration occurs, the unit must be stopped immediately.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 10, 'What is required before entering an enclosed space?', 'A) A permit-to-work', 'B) A flashlight', 'C) A lifejacket', 'D) A fire extinguisher', 'A', NULL, NULL, 'Entry into an enclosed space, such as a ballast tank, requires a strict permit-to-work system. The atmosphere must be tested for oxygen levels, which must be at least 20.9%, and checked for toxic or flammable gases. Ventilation must run continuously during the operation.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 11, 'What is the minimum acceptable oxygen level?', 'A) 10%', 'B) 15%', 'C) 20.9%', 'D) 50%', 'C', NULL, NULL, 'Entry into an enclosed space, such as a ballast tank, requires a strict permit-to-work system. The atmosphere must be tested for oxygen levels, which must be at least 20.9%, and checked for toxic or flammable gases. Ventilation must run continuously during the operation.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 12, 'How should ventilation be managed?', 'A) Turned off', 'B) Run for 5 minutes', 'C) Run continuously', 'D) Only run if it gets hot', 'C', NULL, NULL, 'Entry into an enclosed space, such as a ballast tank, requires a strict permit-to-work system. The atmosphere must be tested for oxygen levels, which must be at least 20.9%, and checked for toxic or flammable gases. Ventilation must run continuously during the operation.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 13, 'Why is ballast water exchange conducted?', 'A) To improve speed', 'B) To prevent transfer of harmful organisms', 'C) To cool the engine', 'D) To clean the tanks', 'B', NULL, NULL, 'To prevent the transfer of harmful aquatic organisms, vessels must conduct ballast water exchange mid-ocean, at least 200 nautical miles from the nearest land and in water at least 200 meters deep. The sequential method or the flow-through method can be used.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 14, 'How far from land must the exchange occur?', 'A) 10 nm', 'B) 50 nm', 'C) 100 nm', 'D) 200 nm', 'D', NULL, NULL, 'To prevent the transfer of harmful aquatic organisms, vessels must conduct ballast water exchange mid-ocean, at least 200 nautical miles from the nearest land and in water at least 200 meters deep. The sequential method or the flow-through method can be used.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 15, 'What are the two approved methods?', 'A) Heating and cooling', 'B) Sequential and flow-through', 'C) Pumping and draining', 'D) Filtering and chemical', 'B', NULL, NULL, 'To prevent the transfer of harmful aquatic organisms, vessels must conduct ballast water exchange mid-ocean, at least 200 nautical miles from the nearest land and in water at least 200 meters deep. The sequential method or the flow-through method can be used.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 16, 'Where is emergency steering activated from?', 'A) The bridge', 'B) The engine control room', 'C) The steering gear room', 'D) The galley', 'C', NULL, NULL, 'In the event of a main steering gear failure, the emergency steering system must be activated from the steering gear room. Communication between the bridge and the steering room is established via sound-powered telephones. Regular drills must be conducted every three months.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 17, 'How do the bridge and steering room communicate?', 'A) VHF radio', 'B) Hand signals', 'C) Sound-powered telephones', 'D) Email', 'C', NULL, NULL, 'In the event of a main steering gear failure, the emergency steering system must be activated from the steering gear room. Communication between the bridge and the steering room is established via sound-powered telephones. Regular drills must be conducted every three months.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 18, 'How often must emergency steering drills be conducted?', 'A) Every week', 'B) Every month', 'C) Every three months', 'D) Every year', 'C', NULL, NULL, 'In the event of a main steering gear failure, the emergency steering system must be activated from the steering gear room. Communication between the bridge and the steering room is established via sound-powered telephones. Regular drills must be conducted every three months.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 19, 'What is the primary use of the auxiliary boiler?', 'A) Propulsion', 'B) Heating fuel oil and accommodations', 'C) Generating electricity', 'D) Cooling the engine', 'B', NULL, NULL, 'The auxiliary boiler provides steam for heating fuel oil and accommodations. Water level must be strictly monitored; a low water level can lead to severe damage or explosion. Feed water is treated with chemicals to prevent scale formation and corrosion.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 20, 'What is the danger of a low water level?', 'A) Freezing', 'B) Loss of speed', 'C) Severe damage or explosion', 'D) High pressure', 'C', NULL, NULL, 'The auxiliary boiler provides steam for heating fuel oil and accommodations. Water level must be strictly monitored; a low water level can lead to severe damage or explosion. Feed water is treated with chemicals to prevent scale formation and corrosion.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 21, 'Why are chemicals added to the feed water?', 'A) To make it boil faster', 'B) To prevent scale and corrosion', 'C) To cool it down', 'D) To change its color', 'B', NULL, NULL, 'The auxiliary boiler provides steam for heating fuel oil and accommodations. Water level must be strictly monitored; a low water level can lead to severe damage or explosion. Feed water is treated with chemicals to prevent scale formation and corrosion.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 22, 'What should synthetic ropes be inspected for?', 'A) Rust', 'B) Chafing and UV degradation', 'C) Paint marks', 'D) Weight', 'B', NULL, NULL, 'Mooring lines are subject to heavy wear and tear. Synthetic ropes must be inspected regularly for chafing, cuts, and UV degradation. Wire ropes should be greased to prevent rust. Snap-back zones must be clearly marked and avoided by the crew during operations.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 23, 'How are wire ropes maintained?', 'A) Washing with water', 'B) Greasing', 'C) Heating', 'D) Cutting', 'B', NULL, NULL, 'Mooring lines are subject to heavy wear and tear. Synthetic ropes must be inspected regularly for chafing, cuts, and UV degradation. Wire ropes should be greased to prevent rust. Snap-back zones must be clearly marked and avoided by the crew during operations.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 24, 'What must crew avoid during mooring?', 'A) The bridge', 'B) The galley', 'C) Snap-back zones', 'D) The anchor', 'C', NULL, NULL, 'Mooring lines are subject to heavy wear and tear. Synthetic ropes must be inspected regularly for chafing, cuts, and UV degradation. Wire ropes should be greased to prevent rust. Snap-back zones must be clearly marked and avoided by the crew during operations.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 25, 'Can plastics be discharged into the sea?', 'A) Yes, if ground up', 'B) Yes, beyond 12 miles', 'C) No, it is strictly prohibited', 'D) Only in special areas', 'C', NULL, NULL, 'Under MARPOL Annex V, the discharge of all plastics into the sea is strictly prohibited. Food waste may be discharged if the vessel is more than 3 nautical miles from land and equipped with a comminuter, or 12 nautical miles without one. All disposals must be recorded in the Garbage Record Book.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 26, 'How far from land can un-ground food waste be discharged?', 'A) 3 nm', 'B) 12 nm', 'C) 25 nm', 'D) 50 nm', 'B', NULL, NULL, 'Under MARPOL Annex V, the discharge of all plastics into the sea is strictly prohibited. Food waste may be discharged if the vessel is more than 3 nautical miles from land and equipped with a comminuter, or 12 nautical miles without one. All disposals must be recorded in the Garbage Record Book.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 27, 'Where must disposals be recorded?', 'A) Oil Record Book', 'B) Official Logbook', 'C) Garbage Record Book', 'D) Deck Log', 'C', NULL, NULL, 'Under MARPOL Annex V, the discharge of all plastics into the sea is strictly prohibited. Food waste may be discharged if the vessel is more than 3 nautical miles from land and equipped with a comminuter, or 12 nautical miles without one. All disposals must be recorded in the Garbage Record Book.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (2, 'reading', 28, 'What drives the turbocharger?', 'A) Electricity', 'B) Steam', 'C) Exhaust gases', 'D) Hydraulic fluid', 'C', NULL, NULL, 'The turbocharger increases the power output of the main engine by forcing more air into the cylinders. It is driven by the engine''s exhaust gases. Routine maintenance includes washing the compressor side with fresh water while the engine is running at reduced load.');
