INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 1, 'How often must lifeboats be visually inspected?', 'A) Weekly', 'B) Daily', 'C) Monthly', 'D) Yearly', 'A', NULL, NULL, 'The SOLAS convention requires that all lifeboats be visually inspected weekly. The lifeboat engine must also be run for a total of not less than 3 minutes to ensure it is in working order.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 2, 'What convention mandates this?', 'A) MARPOL', 'B) SOLAS', 'C) STCW', 'D) MLC', 'B', NULL, NULL, 'The SOLAS convention requires that all lifeboats be visually inspected weekly. The lifeboat engine must also be run for a total of not less than 3 minutes to ensure it is in working order.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 3, 'How long must the engine be run weekly?', 'A) 1 minute', 'B) 3 minutes', 'C) 5 minutes', 'D) 10 minutes', 'B', NULL, NULL, 'The SOLAS convention requires that all lifeboats be visually inspected weekly. The lifeboat engine must also be run for a total of not less than 3 minutes to ensure it is in working order.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 4, 'What is the maximum allowed oil content?', 'A) 5 ppm', 'B) 15 ppm', 'C) 50 ppm', 'D) 100 ppm', 'B', NULL, NULL, 'The Oily Water Separator (OWS) ensures that bilge water discharged overboard contains less than 15 ppm of oil. The 15 ppm bilge alarm continuously monitors the discharge. If the alarm triggers, a 3-way valve recirculates the water back to the bilge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 5, 'What equipment monitors the discharge?', 'A) The 15 ppm bilge alarm', 'B) The main engine', 'C) The radar', 'D) The ballast pump', 'A', NULL, NULL, 'The Oily Water Separator (OWS) ensures that bilge water discharged overboard contains less than 15 ppm of oil. The 15 ppm bilge alarm continuously monitors the discharge. If the alarm triggers, a 3-way valve recirculates the water back to the bilge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 6, 'What happens if the alarm triggers?', 'A) The ship stops', 'B) The valve recirculates water', 'C) The alarm breaks', 'D) Oil is pumped overboard', 'B', NULL, NULL, 'The Oily Water Separator (OWS) ensures that bilge water discharged overboard contains less than 15 ppm of oil. The 15 ppm bilge alarm continuously monitors the discharge. If the alarm triggers, a 3-way valve recirculates the water back to the bilge.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 7, 'What causes ship sweat?', 'A) Warm hull', 'B) Heavy rain', 'C) Hull colder than dew point', 'D) Too much cargo', 'C', NULL, NULL, 'Proper ventilation of cargo holds is critical to prevent sweat. Ship sweat occurs when the ship''s hull is colder than the dew point of the air inside the hold. This can lead to severe cargo damage if not managed.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 8, 'Why must cargo holds be ventilated?', 'A) To prevent sweat', 'B) To dry the paint', 'C) To cool the engine', 'D) To increase speed', 'A', NULL, NULL, 'Proper ventilation of cargo holds is critical to prevent sweat. Ship sweat occurs when the ship''s hull is colder than the dew point of the air inside the hold. This can lead to severe cargo damage if not managed.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 9, 'What happens if sweat forms?', 'A) Faster journey', 'B) Cargo damage', 'C) Better stability', 'D) Engine failure', 'B', NULL, NULL, 'Proper ventilation of cargo holds is critical to prevent sweat. Ship sweat occurs when the ship''s hull is colder than the dew point of the air inside the hold. This can lead to severe cargo damage if not managed.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 10, 'What is the pressure of the starting air?', 'A) 10 bar', 'B) 20 bar', 'C) 30 bar', 'D) 40 bar', 'C', NULL, NULL, 'The starting air system provides high-pressure air at 30 bar to turn the main engine over during starting. The air compressors charge the air receivers automatically when the pressure drops.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 11, 'What is the purpose of this air?', 'A) To clean the deck', 'B) To turn the main engine over', 'C) To inflate tires', 'D) To cool the oil', 'B', NULL, NULL, 'The starting air system provides high-pressure air at 30 bar to turn the main engine over during starting. The air compressors charge the air receivers automatically when the pressure drops.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 12, 'How are the air receivers charged?', 'A) Automatically by air compressors', 'B) Manually by crew', 'C) By the turbocharger', 'D) By the wind', 'A', NULL, NULL, 'The starting air system provides high-pressure air at 30 bar to turn the main engine over during starting. The air compressors charge the air receivers automatically when the pressure drops.');
INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 13, 'What is a snap-back zone?', 'A) A resting area', 'B) Area where a broken line recoils', 'C) A dining room', 'D) A cargo hold', 'B', NULL, NULL, 'A snap-back zone is the area where a parted mooring line could recoil with deadly force. Crew members must never stand in these zones during mooring operations to prevent serious injuries.');
