INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 16, 'What is a common use for centrifugal pumps?', 'A) Fuel injection', 'B) Ballast and cooling water', 'C) Air compression', 'D) Steering', 'B', NULL, NULL, 'Centrifugal pumps are widely used for handling ballast and cooling water. These pumps must be primed before starting. Running them dry can destroy the mechanical seal.');
