INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 19, 'What does ECDIS replace?', 'A) Paper charts', 'B) The compass', 'C) The radar', 'D) The VHF radio', 'A', NULL, NULL, 'The Electronic Chart Display and Information System (ECDIS) replaces traditional paper charts. Navigators must ensure that the electronic navigational charts (ENC) are updated weekly.');
