INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 22, 'What is the incinerator used for?', 'A) Cooking food', 'B) Heating water', 'C) Burning waste', 'D) Generating electricity', 'C', NULL, NULL, 'The ship''s incinerator is used to burn solid waste and waste oil. However, burning PVC plastics or materials containing heavy metals is strictly prohibited due to toxic emissions.');
