INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 25, 'How many independent power units are required?', 'A) One', 'B) At least two', 'C) Three', 'D) Four', 'B', NULL, NULL, 'The steering gear must have at least two independent hydraulic power units. In restricted waters, both power units must be running simultaneously to ensure redundancy.');
