INSERT INTO questions (bank_id, section, original_id, question, option_a, option_b, option_c, option_d, correct_option, audio, context, passage) VALUES (3, 'reading', 28, 'What do hatch covers prevent?', 'A) Wind', 'B) Sunlight', 'C) Water ingress', 'D) Pirates', 'C', NULL, NULL, 'Weather deck hatch covers prevent water ingress into the cargo holds. Before sea passage, all securing cleats must be tightened and cross-joints inspected to ensure water-tightness.');
