CREATE TABLE IF NOT EXISTS questions (
    id INT AUTO_INCREMENT PRIMARY KEY,
    bank_id INT,
    section VARCHAR(50),
    original_id INT,
    question TEXT,
    option_a TEXT,
    option_b TEXT,
    option_c TEXT,
    option_d TEXT,
    correct_option CHAR(1),
    audio VARCHAR(255) NULL,
    context TEXT NULL,
    passage TEXT NULL
);

